// ── 3. CSRF token generation and validation ───────────────────
import { randomBytes, timingSafeEqual } from 'node:crypto';

function generateCSRFToken() {
  return randomBytes(32).toString('hex');  // 256-bit unpredictable token
}

function validateCSRFToken(sessionToken, submittedToken) {
  if (!sessionToken || !submittedToken) return false;
  const a = Buffer.from(sessionToken,  'hex');
  const b = Buffer.from(submittedToken, 'hex');
  return a.length === b.length && timingSafeEqual(a, b); // Constant-time comparison
}

// In a request handler:
function csrfMiddleware(req, res, next) {
  if (['POST', 'PUT', 'PATCH', 'DELETE'].includes(req.method)) {
    const sessionToken   = req.session.csrfToken;
    const submittedToken = req.headers['x-csrf-token'] || req.body._csrf;
    if (!validateCSRFToken(sessionToken, submittedToken)) {
      return res.status(403).json({ error: 'Invalid CSRF token' });
    }
  }
  next();
}

// ── 4. SSRF mitigation: URL validation ───────────────────────
import { URL } from 'node:url';
import dns from 'node:dns/promises';

const PRIVATE_IP_RANGES = [/^10\./, /^172\.(1[6-9]|2\d|3[01])\./, /^192\.168\./, /^127\./, /^169\.254\./, /^::1$/, /^fc00:/];

async function isSafeURL(urlString, allowedDomains) {
  try {
    const url = new URL(urlString);
    if (!['http:', 'https:'].includes(url.protocol)) return false; // Block file://, ftp://, etc.
    if (!allowedDomains.some(d => url.hostname.endsWith(d))) return false; // Domain allowlist
    const addresses = await dns.resolve4(url.hostname).catch(() => []);
    if (addresses.some(ip => PRIVATE_IP_RANGES.some(r => r.test(ip)))) return false; // Block private IPs
    return true;
  } catch { return false; }
}

